<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { AlertTriangle, BarChart3, CheckCircle2, Image as ImageIcon, Leaf, LoaderCircle, Upload, Wheat } from 'lucide-vue-next'
import { imageUrl, predictGrowthStage, segmentationAlgorithms } from '../services/imageApi'
import { analyzeGrowth, deleteGrowthHistory, getGrowthHistory, getGrowthHistoryItem, growthMediaUrl } from '../services/growthApi'
import { getForecastStatus, predictFutureGrowth } from '../services/forecastApi'
import { loadLatestAnalysis, saveLatestAnalysis } from '../services/analysisSession'

const selectedAlgorithm = ref('ExG')
const plotId = ref('')
const selectedFile = ref(null)
const previewUrl = ref('')
const result = ref(null)
const loading = ref(false)
const stageLoading = ref(false)
const stageResult = ref(null)
const syncedFromRecognition = ref(false)
const errorMessage = ref('')
const history = ref([])
const dragging = ref(false)
const fileInput = ref(null)
const forecastStatus = ref({ status: 'checking', enabled: false })
const forecastError = ref('')
const forecastResult = ref(null)
const forecastLoading = ref(false)
const captureDate = ref('')
const forecastLocation = ref('')
const forecastLatitude = ref('')
const forecastLongitude = ref('')
const growth = computed(() => result.value?.growth_analysis?.metrics || null)
function buildVigorFallback(metrics) {
  if (!metrics?.vegetation_coverage || !metrics?.green_degree || !metrics?.distribution_uniformity) return null
  const coverage = Number(metrics.vegetation_coverage.fraction || 0)
  const green = metrics.green_degree.mean_green_channel_ratio == null ? 0 : Number(metrics.green_degree.mean_green_channel_ratio)
  const cv = metrics.distribution_uniformity.coefficient_of_variation
  const coverageScore = Math.max(0, Math.min(100, coverage / 0.75 * 100))
  const greennessScore = Math.max(0, Math.min(100, green * 100))
  const uniformityScore = cv == null ? 0 : Math.max(0, Math.min(100, (1 - Number(cv) / 1.5) * 100))
  const score = coverageScore * 0.45 + greennessScore * 0.35 + uniformityScore * 0.2
  const risks = metrics.image_quality?.risk_flags || []
  const blocking = []
  if (Number(metrics.vegetation_coverage.vegetation_pixel_count || 0) === 0) blocking.push('没有检测到可见植被前景')
  if (risks.some(item => item.includes('偏暗'))) blocking.push('画面偏暗')
  if (risks.some(item => item.includes('过曝'))) blocking.push('画面过曝')
  return {
    vigor_score: score,
    vigor_level: blocking.length ? null : score >= 80 ? '长势较好' : score >= 60 ? '长势一般' : '长势较弱',
    coverage_score: coverageScore,
    greenness_score: greennessScore,
    uniformity_score: uniformityScore,
    reliability: blocking.length ? '较低' : risks.length ? '中等' : '较高',
    strengths: [],
    improvement_suggestions: blocking.length ? ['请重新拍摄清晰、光照均匀且植株完整可见的图片。'] : [],
    quality_blocking_reasons: blocking,
    evaluation_version: 'growth-vigor-v1.1-rule',
  }
}

const vigor = computed(() => {
  const nested = result.value?.growth_analysis?.vigor_assessment
  if (nested) return nested
  const fallback = buildVigorFallback(result.value?.growth_analysis?.metrics)
  if (fallback) return fallback
  if (result.value?.vigor_score != null) return {
    vigor_score: result.value.vigor_score,
    vigor_level: result.value.vigor_level,
    coverage_score: result.value.coverage_score,
    greenness_score: result.value.greenness_score,
    uniformity_score: result.value.uniformity_score,
    reliability: result.value.reliability,
    strengths: result.value.strengths || [],
    improvement_suggestions: result.value.improvement_suggestions || [],
    evaluation_version: result.value.evaluation_version || 'growth-vigor-v1.1-rule',
    quality_blocking_reasons: [],
  }
  return null
})
const vigorReason = computed(() => {
  const reasons = vigor.value?.quality_blocking_reasons || []
  return reasons.length ? `暂不评级：${reasons.join('、')}。请重新拍摄清晰、光照均匀且植株完整可见的图片。` : '综合分来自当前图片的规则计算；等级需要有效图像质量才能输出。'
})
const hasAnalysisInput = computed(() => Boolean(selectedFile.value || result.value))
const percent = value => value == null ? '—' : `${Number(value).toFixed(2)}%`
const ratioPercent = value => value == null ? '—' : `${(Number(value) * 100).toFixed(2)}%`
function acceptFile(file) { if (!file) return; if (!/\.(jpg|jpeg|png)$/i.test(file.name || '') && !['image/png', 'image/jpeg'].includes(file.type)) { errorMessage.value = '仅支持 JPG、JPEG 或 PNG 图片。'; return }; if (previewUrl.value) URL.revokeObjectURL(previewUrl.value); selectedFile.value = file; previewUrl.value = URL.createObjectURL(file); result.value = null; stageResult.value = null; forecastResult.value = null; syncedFromRecognition.value = false; errorMessage.value = '' }
function chooseFile(event) { acceptFile(event.target.files?.[0]); event.target.value = '' }
function handleDrop(event) { dragging.value = false; acceptFile(event.dataTransfer?.files?.[0]) }
async function runAnalysis() { if (!selectedFile.value && result.value) { syncedFromRecognition.value = true; errorMessage.value = ''; return }; if (!selectedFile.value) { errorMessage.value = '请先选择一张 JPG、JPEG 或 PNG 图片。'; return }; loading.value = true; errorMessage.value = ''; result.value = null; try { result.value = await analyzeGrowth(selectedFile.value, undefined, selectedAlgorithm.value, plotId.value.trim()); stageResult.value = result.value.growth_stage || null; syncedFromRecognition.value = false; saveLatestAnalysis({ result: { ...result.value, vigor_score: vigor.value?.vigor_score, vigor_level: vigor.value?.vigor_level, coverage_score: vigor.value?.coverage_score, greenness_score: vigor.value?.greenness_score, uniformity_score: vigor.value?.uniformity_score }, stageResult: stageResult.value, algorithm: selectedAlgorithm.value, fileName: selectedFile.value.name }); await loadHistory() } catch (error) { errorMessage.value = error.message || '分析未完成，请稍后重试。' } finally { loading.value = false } }
async function runStagePrediction() { if (!selectedFile.value && !result.value) { errorMessage.value = '请先上传图片，或从图像识别页完成一次分析。'; return }; stageLoading.value = true; errorMessage.value = ''; stageResult.value = null; try { let file = selectedFile.value; if (!file && result.value?.original_url) { const response = await fetch(imageUrl(result.value.original_url)); if (!response.ok) throw new Error('最近一次分析图片已不可访问，请重新上传。'); const blob = await response.blob(); file = new File([blob], 'synced-analysis.jpg', { type: blob.type || 'image/jpeg' }) }; stageResult.value = await predictGrowthStage(file); saveLatestAnalysis({ result: result.value, stageResult: stageResult.value, algorithm: result.value?.algorithm, fileName: selectedFile.value?.name }) } catch (error) { errorMessage.value = error.message || '生育期识别未完成，请稍后重试。' } finally { stageLoading.value = false } }
async function runForecast() { if (!result.value) { errorMessage.value = '请先完成当前图片的长势分析。'; return }; forecastLoading.value = true; forecastError.value = ''; errorMessage.value = ''; try { const currentVigor = vigor.value || {}; const response = await fetch('/api/growth-trend/predict', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ growth_stage: stageResult.value?.predicted_stage_name || result.value.growth_stage?.predicted_stage_name || '', vigor_score: currentVigor.vigor_score ?? null, vigor_level: currentVigor.vigor_level || null, vegetation_coverage: result.value.growth_analysis?.metrics?.vegetation_coverage?.fraction ?? null, greenness: result.value.growth_analysis?.metrics?.green_degree?.mean_green_channel_ratio ?? null, uniformity_cv: result.value.growth_analysis?.metrics?.distribution_uniformity?.coefficient_of_variation ?? null, stage_confidence: stageResult.value?.confidence ?? result.value.growth_stage?.confidence ?? 0, capture_date: captureDate.value || null, location: forecastLocation.value.trim() || null, weather_status: 'unavailable', weather_risks: [] }) }); const data = await response.json(); if (!response.ok) throw new Error(data?.error?.message || '未来趋势检查未完成。'); forecastResult.value = data; } catch (error) { forecastError.value = error.message || '未来趋势检查未完成，请稍后重试。'; errorMessage.value = forecastError.value } finally { forecastLoading.value = false } }
function sourceUrl(path) { return path ? (path.startsWith('/media/') ? growthMediaUrl(path) : imageUrl(path)) : '' }
async function loadHistory() { try { history.value = await getGrowthHistory() } catch { /* 历史接口失败不影响当前图片分析 */ } }
async function openHistory(item) { try { const detail = await getGrowthHistoryItem(item.analysis_id); result.value = detail; selectedAlgorithm.value = detail.algorithm || 'ExG'; plotId.value = detail.plot_id || ''; stageResult.value = detail.growth_stage || null; syncedFromRecognition.value = true; saveLatestAnalysis({ result: { ...detail, vigor_score: detail.vigor_score ?? vigor.value?.vigor_score, vigor_level: detail.vigor_level ?? vigor.value?.vigor_level }, stageResult: stageResult.value, algorithm: detail.algorithm || 'ExG' }); errorMessage.value = '' } catch (error) { errorMessage.value = error.message || '历史记录读取失败。' } }
async function deleteHistory(item) { if (!window.confirm(`确定删除 ${item.analysis_id} 的分析记录吗？原图、掩膜、叠加图和 JSON 记录都会删除。`)) return; try { await deleteGrowthHistory(item.analysis_id); history.value = history.value.filter(entry => entry.analysis_id !== item.analysis_id); if (result.value?.analysis_id === item.analysis_id || result.value?.task_id === item.analysis_id) { result.value = null; stageResult.value = null } } catch (error) { errorMessage.value = error.message || '历史记录删除失败。' } }
onMounted(async () => { const saved = loadLatestAnalysis(); if (saved?.result) { result.value = saved.result; selectedAlgorithm.value = saved.algorithm || saved.result.algorithm || 'ExG'; plotId.value = saved.result.plot_id || ''; stageResult.value = saved.stageResult || saved.result.growth_stage || null; syncedFromRecognition.value = true }; await Promise.allSettled([loadHistory(), fetch('/api/growth-trend/status').then(response => response.ok ? response.json() : Promise.reject(new Error('状态接口返回异常'))).then(value => { forecastStatus.value = value }).catch(error => { forecastStatus.value = { enabled: false, status: 'unavailable', reason: error.message || '独立趋势服务状态暂不可用。' } })]) })
onBeforeUnmount(() => { if (previewUrl.value) URL.revokeObjectURL(previewUrl.value) })
</script>

<template>
  <div class="growth-v1-page">
    <header class="growth-v1-title"><div class="growth-v1-heading"><span class="growth-v1-icon"><Leaf :size="25" /></span><div><p class="eyebrow">IMAGE-BASED GROWTH OBSERVATION</p><h1>小麦长势智能分析</h1><p>从一张小麦照片生成当前长势的可解释规则初评。</p></div></div><span class="status-pill"><span></span>V2.0 · 当前长势分析</span></header>
    <section class="growth-v1-panel growth-v1-controls"><div class="control-upload" :class="{ dragging }" @click="fileInput?.click()" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="handleDrop"><Upload :size="20" /><div><strong>{{ selectedFile?.name || (syncedFromRecognition ? '已同步图像识别结果' : '上传小麦图片') }}</strong><small>{{ syncedFromRecognition ? '来自图像识别页 · 可直接查看长势指标' : '点击或拖拽 JPG、JPEG、PNG 图片到此处' }}</small></div><input ref="fileInput" type="file" accept="image/png,image/jpeg" hidden @change="chooseFile" /></div><label class="plot-id-field">地块编号（可选）<input v-model="plotId" maxlength="80" pattern="[A-Za-z0-9_-]+" placeholder="同一地块请保持一致" /></label><label class="algorithm-select"><span>识别方案</span><select v-model="selectedAlgorithm"><option v-for="item in segmentationAlgorithms" :key="item.name" :value="item.name">{{ item.name }}</option></select></label><button class="run-button" :class="{ 'is-synced': !selectedFile && result }" :disabled="loading || !hasAnalysisInput" @click="runAnalysis"><LoaderCircle v-if="loading" class="spin" :size="17" /><CheckCircle2 v-else-if="!selectedFile && result" :size="17" /><BarChart3 v-else :size="17" />{{ loading ? '正在分析' : (!selectedFile && result ? '已载入分析结果' : '开始分析') }}</button><button class="stage-button" :disabled="stageLoading || (!selectedFile && !result)" @click="runStagePrediction"><LoaderCircle v-if="stageLoading" class="spin" :size="17" /><Wheat v-else :size="17" />{{ stageLoading ? '识别中' : '识别生育期' }}</button></section>
    <p v-if="errorMessage" class="growth-error"><AlertTriangle :size="16" />{{ errorMessage }}</p>
    <section class="growth-v1-panel stage-result-panel"><div class="panel-head"><h2><Wheat :size="17" />生育期识别</h2><span>{{ stageResult?.model_version || '模型待验证' }}</span></div><div v-if="stageResult" class="stage-result-grid"><div class="stage-main"><small>当前图片预测阶段</small><strong>{{ stageResult.predicted_stage_name }}</strong><span>置信度 {{ (stageResult.confidence * 100).toFixed(1) }}% · {{ stageResult.inference_time_seconds.toFixed(3) }} 秒</span><em v-if="stageResult.confidence < 0.5" class="stage-low-confidence">置信度较低，建议结合田间记录复核</em></div><div class="stage-probabilities"><div v-for="(value, name) in stageResult.probabilities" :key="name" class="prob-row"><span>{{ name }}</span><div><i :style="{ width: `${value * 100}%` }"></i></div><b>{{ (value * 100).toFixed(1) }}%</b></div></div></div><div v-else class="stage-empty"><Wheat :size="20" /><span>{{ result?.growth_stage_status === 'GROWTH_STAGE_MODEL_UNAVAILABLE' ? '生育期模型待验证，当前只显示长势规则初评。' : '统一分析会自动尝试生育期识别；没有可验证模型时不会生成随机结果。' }}</span></div></section>
    <section class="growth-v1-images"><article class="growth-v1-panel image-panel"><div class="panel-head"><h2><ImageIcon :size="17" />原始图片</h2><span>{{ result ? `${result.width} × ${result.height}` : '等待上传' }}</span></div><div class="image-stage"><img v-if="result" :src="sourceUrl(result.original_url)" alt="上传的原始小麦图片" /><img v-else-if="previewUrl" :src="previewUrl" alt="待分析的小麦图片" /><div v-else class="image-empty"><Upload :size="27" /><span>等待图片</span></div></div></article><article class="growth-v1-panel image-panel"><div class="panel-head"><h2><Leaf :size="17" />植被分割</h2><span>{{ result?.algorithm || '等待分析' }}</span></div><div class="image-stage"><img v-if="result" :src="sourceUrl(result.mask_url)" alt="实际生成的植被分割掩膜" /><div v-else class="image-empty"><Leaf :size="27" /><span>分析后显示掩膜</span></div></div></article><article class="growth-v1-panel image-panel"><div class="panel-head"><h2><Wheat :size="17" />结果叠加</h2><span>可见植被区域</span></div><div class="image-stage"><img v-if="result" :src="sourceUrl(result.overlay_url)" alt="原图与植被掩膜叠加结果" /><div v-else class="image-empty"><Wheat :size="27" /><span>分析后显示叠加图</span></div></div></article></section>
    <section class="growth-v1-metrics"><article class="growth-v1-panel metric-card coverage-card"><div class="donut" :style="{ '--coverage': `${growth ? growth.vegetation_coverage.percentage : 0}%` }"><div><strong>{{ growth ? percent(growth.vegetation_coverage.percentage) : '—' }}</strong><small>可见覆盖率</small></div></div><div><h2>植被覆盖率</h2><p>{{ growth ? `${growth.vegetation_coverage.vegetation_pixel_count.toLocaleString()} / ${growth.vegetation_coverage.valid_pixel_count.toLocaleString()} 像素` : '等待真实分割结果' }}</p></div></article><article class="growth-v1-panel metric-card"><span class="metric-icon"><Leaf :size="19" /></span><div><h2>绿色程度</h2><strong>{{ growth ? percent(growth.green_degree.percentage) : '—' }}</strong><p>前景区域 G 通道比例</p></div></article><article class="growth-v1-panel metric-card"><span class="metric-icon"><BarChart3 :size="19" /></span><div><h2>分布均匀度</h2><strong>{{ growth ? (growth.distribution_uniformity.coefficient_of_variation == null ? '—' : growth.distribution_uniformity.coefficient_of_variation.toFixed(3)) : '—' }}</strong><p>网格覆盖率变异系数</p></div></article><article class="growth-v1-panel metric-card quality-card"><span class="metric-icon"><CheckCircle2 :size="19" /></span><div><h2>图像质量</h2><strong>{{ growth ? `${growth.image_quality.width}×${growth.image_quality.height}` : '—' }}</strong><p>{{ growth ? (growth.image_quality.risk_flags.length ? growth.image_quality.risk_flags[0] : '未发现明显亮度风险') : '等待图片分析' }}</p></div></article></section>
    <section v-if="result" class="growth-v1-panel vigor-panel"><div class="panel-head"><h2><Leaf :size="17" />长势综合评价</h2><span>{{ vigor?.evaluation_version || '等待统一分析' }} · 规则初评</span></div><div v-if="vigor" class="vigor-layout"><div class="vigor-score-wrap"><div class="vigor-score-ring" :style="{ '--score': `${vigor.vigor_score}%` }"><div><strong>{{ vigor.vigor_score.toFixed(1) }}</strong><small>综合分 / 100</small></div></div><b :class="{ muted: !vigor.vigor_level }">{{ vigor.vigor_level || '暂不评级' }}</b><small>可靠性：{{ vigor.reliability || '—' }}</small></div><div class="vigor-components"><div v-for="item in [{ key: 'coverage_score', label: '覆盖评分' }, { key: 'greenness_score', label: '绿色评分' }, { key: 'uniformity_score', label: '均匀评分' }]" :key="item.key" class="vigor-component"><span>{{ item.label }}</span><div><i :style="{ width: `${vigor[item.key]}%` }"></i></div><b>{{ vigor[item.key].toFixed(1) }}</b></div><div class="vigor-notes"><div><strong>主要优势</strong><span v-for="item in vigor.strengths" :key="item">{{ item }}</span></div><div><strong>需要改善</strong><span v-for="item in vigor.improvement_suggestions" :key="item">{{ item }}</span></div></div></div></div><div v-else class="vigor-no-data">当前记录来自旧版接口，尚未返回 V1.1 综合评分。请点击“开始分析”重新生成统一长势结果。</div><p class="vigor-boundary">{{ vigor ? vigorReason : '当前记录没有综合评分字段。' }} 当前结果是基于覆盖、绿色程度和空间均匀度的图像表观初评，尚未进行生育期校正和专家标签校准，不能直接等同于农学诊断。</p></section>
    <section v-if="growth" class="growth-v1-bottom"><article class="growth-v1-panel heatmap-panel"><div class="panel-head"><h2><BarChart3 :size="17" />植被区域分布</h2><span>{{ growth.distribution_uniformity.grid_rows }} × {{ growth.distribution_uniformity.grid_cols }} 网格</span></div><div class="heatmap-grid"><span v-for="(value, index) in growth.distribution_uniformity.cell_coverage_fractions" :key="index" :style="{ '--heat': value }" :title="`区域覆盖率 ${(value * 100).toFixed(2)}%`">{{ (value * 100).toFixed(0) }}</span></div><small class="heatmap-note">数字为各区域覆盖率百分比；这是图像空间分布指标，不代表真实田间密度。</small></article><article class="growth-v1-panel report-panel"><div class="panel-head"><h2><Leaf :size="17" />小麦植株分析</h2><span>{{ result.algorithm }} · 当前图片</span></div><div class="report-lines"><p><b>植株状态</b><span>{{ vigor?.vigor_level || '暂不评级' }}</span></p><p><b>综合评分</b><span>{{ vigor ? vigor.vigor_score.toFixed(1) + ' / 100' : '—' }}</span></p><p><b>分析可靠性</b><span>{{ vigor?.reliability || '—' }}</span></p><p><b>可见覆盖率</b><span>{{ ratioPercent(growth.vegetation_coverage.fraction) }}</span></p><p><b>处理耗时</b><span>{{ (result.processing_time ?? result.analysis_time_seconds).toFixed(3) }} 秒</span></p></div><div class="notice"><AlertTriangle :size="16" /><span>这里展示的是当前小麦植株的图像表观分析，不是最终农学诊断；未来趋势预测模型待建立。</span></div></article></section>
    <section class="growth-v1-panel history-panel"><div class="panel-head"><h2><CheckCircle2 :size="17" />历史分析</h2><span>{{ history.length }} 条</span></div><div v-if="history.length" class="history-list"><div v-for="item in history" :key="item.analysis_id" class="history-item" @click="openHistory(item)"><span><b>{{ item.vigor_level || '暂不评级' }}</b><small>{{ item.completed_at_utc || item.created_at_utc }}</small></span><strong>{{ item.vigor_score == null ? '—' : Number(item.vigor_score).toFixed(1) }}</strong><em>{{ item.reliability || '—' }}</em><button class="history-delete" @click.stop="deleteHistory(item)">删除</button></div></div><div v-else class="history-empty">完成一次真实图片分析后，历史记录会显示在这里。</div></section>
    <section class="growth-v1-panel limitation-panel"><h2>指标解释与使用边界</h2><div><span>覆盖率 = 前景像素 / 有效像素</span><span>绿色程度 ≠ 叶绿素含量</span><span>均匀度 ≠ 植株密度</span><span>单幅图像 ≠ 生长趋势预测</span></div></section>
  </div>
</template>

<style scoped>
.growth-v1-page{position:relative;isolation:isolate;padding:8px 0 30px;color:#edf5e7;min-height:calc(100vh - 150px)}.growth-v1-page::before{content:"";position:absolute;inset:-24px -28px -20px;z-index:-2;background:url('../assets/growth-wheat-field-photo.jpg') center/cover;filter:blur(5px) brightness(.52) saturate(.8)}.growth-v1-page::after{content:"";position:absolute;inset:-24px -28px -20px;z-index:-1;background:linear-gradient(110deg,#071b14e8,#0c2d1dc7 55%,#061810db)}
.growth-v1-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px;gap:20px}.growth-v1-heading{display:flex;align-items:center;gap:14px}.growth-v1-icon{width:48px;height:48px;border-radius:13px;display:grid;place-items:center;background:#75d66b25;color:#a5e58a}.eyebrow{font-size:9px;letter-spacing:1.5px;color:#a5e58a;margin:0 0 5px}.growth-v1-title h1{font-size:28px;font-weight:500;margin:0 0 5px}.growth-v1-title p:not(.eyebrow){font-size:11px;color:#b9cfb4;margin:0}.status-pill{font-size:10px;color:#b9dfaa;border:1px solid #95d17b49;border-radius:20px;padding:8px 12px;background:#15392388;white-space:nowrap}.status-pill span{display:inline-block;width:6px;height:6px;border-radius:50%;background:#75d66b;margin-right:7px}
