.growth-v1-bottom{display:grid;grid-template-columns:1.1fr 1fr;gap:15px;margin-bottom:15px}.heatmap-panel,.report-panel{padding:16px}.heatmap-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin:15px 0 9px}.heatmap-grid span{height:40px;display:grid;place-items:center;border-radius:5px;color:#071b14;font-size:10px;background:rgba(117,214,107,calc(.12 + var(--heat)*.8));border:1px solid #b4ed9d30}.heatmap-note{font-size:9px;color:#9fb7a4;line-height:1.5}.report-lines{display:grid;gap:8px}.report-lines p{display:flex;justify-content:space-between;margin:0;border-bottom:1px solid #a5e58a16;padding-bottom:8px;font-size:10px}.report-lines b{font-weight:400;color:#9fb7a4}.report-lines span{color:#e5f0e0}.notice{display:flex;gap:7px;align-items:flex-start;margin-top:14px;padding:9px;background:#d8b65c15;border:1px solid #d8b65c36;border-radius:7px;color:#e0ce96;font-size:9px;line-height:1.6}.limitation-panel{padding:14px 17px;display:flex;align-items:center;justify-content:space-between;gap:15px}.limitation-panel h2{font-size:11px;color:#cfe2c8}.limitation-panel>div{display:flex;flex-wrap:wrap;gap:8px}.limitation-panel span{font-size:9px;color:#aac4a3;padding:6px 8px;background:#a5e58a0d;border:1px solid #a5e58a1d;border-radius:6px}
